// decodeUnicodeTestCorpus returns the exact pinned source file for tests.
func decodeUnicodeTestCorpus(encoded string) []byte {
	compressed, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic("invalid generated Unicode corpus encoding: " + err.Error())
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		panic("invalid generated Unicode corpus gzip: " + err.Error())
	}
	defer reader.Close()
	data, err := io.ReadAll(reader)
	if err != nil {
		panic("invalid generated Unicode corpus payload: " + err.Error())
	}
	return data
}
